from copy import deepcopy
from pathlib import Path
from zipfile import ZipFile
from lxml import etree

from docx import Document
from docx.enum.table import WD_CELL_VERTICAL_ALIGNMENT
from docx.enum.text import WD_ALIGN_PARAGRAPH, WD_BREAK
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
from docx.shared import Cm, Pt, RGBColor

SOURCE = Path('Практика_Звіт_Теплий.docx')
OUTPUT = Path('Практика_Звіт_Теплий_повний.docx')

doc = Document(SOURCE)
body = doc._body._element
conclusion = next(p for p in doc.paragraphs if p.text.strip().lower() == 'висновок')
children = list(body)
conclusion_index = children.index(conclusion._p)
sect_pr = body.sectPr
# Detach the existing conclusion and everything after it, preserving the XML exactly.
tail = [element for element in children[conclusion_index:] if element is not sect_pr]
for element in tail:
    body.remove(element)


def set_font(run, name='Times New Roman', size=14, bold=None, italic=None, color=None):
    run.font.name = name
    run._element.rPr.rFonts.set(qn('w:eastAsia'), name)
    run.font.size = Pt(size)
    if bold is not None:
        run.bold = bold
    if italic is not None:
        run.italic = italic
    if color is not None:
        run.font.color.rgb = RGBColor(*color)


def page_break():
    p = doc.add_paragraph(style='Normal')
    p.paragraph_format.first_line_indent = Cm(0)
    p.add_run().add_break(WD_BREAK.PAGE)


def heading(text, level):
    p = doc.add_paragraph(style=f'Heading {level}')
    p.add_run(text)
    if level == 1:
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.keep_with_next = True
    return p


def body_paragraph(text, bold_prefix=None):
    p = doc.add_paragraph(style='Normal')
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    if bold_prefix and text.startswith(bold_prefix):
        r = p.add_run(bold_prefix)
        set_font(r, bold=True)
        r = p.add_run(text[len(bold_prefix):])
        set_font(r)
    else:
        r = p.add_run(text)
        set_font(r)
    return p


def formula(text):
    p = doc.add_paragraph(style='Normal')
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = Cm(0)
    r = p.add_run(text)
    set_font(r, italic=True)
    return p


def code_block(lines):
    p = doc.add_paragraph(style='Normal')
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    pf = p.paragraph_format
    pf.first_line_indent = Cm(0)
    pf.left_indent = Cm(0.8)
    pf.right_indent = Cm(0.4)
    pf.line_spacing = 1.0
    pf.space_before = Pt(4)
    pf.space_after = Pt(4)
    shade = OxmlElement('w:shd')
    shade.set(qn('w:fill'), 'F2F2F2')
    p._p.get_or_add_pPr().append(shade)
    for index, line in enumerate(lines):
        if index:
            p.add_run().add_break()
        r = p.add_run(line)
        set_font(r, name='Courier New', size=10)
    return p


def marker(text):
    p = doc.add_paragraph(style='Normal')
    p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    p.paragraph_format.first_line_indent = Cm(0)
    r = p.add_run(f'[ПОТРІБНО ДОДАТИ РИСУНОК: {text}]')
    set_font(r, bold=True, color=(255, 0, 0))
    return p


def table(caption, headers, rows, widths=None):
    cap = doc.add_paragraph(style='Normal')
    cap.alignment = WD_ALIGN_PARAGRAPH.CENTER
    cap.paragraph_format.first_line_indent = Cm(0)
    r = cap.add_run(caption)
    set_font(r, bold=False)
    t = doc.add_table(rows=1, cols=len(headers))
    t.autofit = True
    borders = OxmlElement('w:tblBorders')
    for edge in ('top', 'left', 'bottom', 'right', 'insideH', 'insideV'):
        border = OxmlElement(f'w:{edge}')
        border.set(qn('w:val'), 'single')
        border.set(qn('w:sz'), '4')
        border.set(qn('w:space'), '0')
        border.set(qn('w:color'), '000000')
        borders.append(border)
    t._tbl.tblPr.append(borders)
    hdr = t.rows[0]
    for i, value in enumerate(headers):
        cell = hdr.cells[i]
        cell.vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
        cell.text = value
        shd = OxmlElement('w:shd')
        shd.set(qn('w:fill'), 'D9E2F3')
        cell._tc.get_or_add_tcPr().append(shd)
        for p in cell.paragraphs:
            p.alignment = WD_ALIGN_PARAGRAPH.CENTER
            p.paragraph_format.first_line_indent = Cm(0)
            p.paragraph_format.space_after = Pt(0)
            for run in p.runs:
                set_font(run, size=10, bold=True)
    for values in rows:
        cells = t.add_row().cells
        for i, value in enumerate(values):
            cells[i].vertical_alignment = WD_CELL_VERTICAL_ALIGNMENT.CENTER
            cells[i].text = str(value)
            for p in cells[i].paragraphs:
                p.alignment = WD_ALIGN_PARAGRAPH.LEFT if i == 0 else WD_ALIGN_PARAGRAPH.CENTER
                p.paragraph_format.first_line_indent = Cm(0)
                p.paragraph_format.space_after = Pt(0)
                p.paragraph_format.line_spacing = 1.0
                for run in p.runs:
                    set_font(run, size=10)
        tr_pr = t.rows[-1]._tr.get_or_add_trPr()
        cant_split = OxmlElement('w:cantSplit')
        tr_pr.append(cant_split)
    # Repeat header row in Word.
    tr_pr = hdr._tr.get_or_add_trPr()
    tbl_header = OxmlElement('w:tblHeader')
    tbl_header.set(qn('w:val'), 'true')
    tr_pr.append(tbl_header)
    doc.add_paragraph(style='Normal').paragraph_format.space_after = Pt(0)
    return t


page_break()
heading("Розділ 5. Реалізація адаптивної системи спрощення геопросторових об’єктів", 1)
body_paragraph("У межах практичної частини розроблено автономну бібліотеку адаптивного спрощення геопросторових геометрій. Її вхідними даними є геометрія у форматі WKT і бажаний відсоток скорочення кількості вершин, а результатом — спрощена геометрія у тому самому форматі. Реалізація не прив’язує координати до конкретної системи відліку: усі відстані та допуски інтерпретуються в одиницях вхідних координат. Основна відмінність від стандартного алгоритму Дугласа–Пекера полягає в тому, що допустиме відхилення змінюється вздовж геометрії відповідно до локальної оцінки складності.")

heading("5.1. Архітектура системи", 2)
body_paragraph("Програмну систему побудовано як набір невеликих компонентів із чітко розділеними обов’язками. Публічний API відокремлено від аналізу складності, геометричного спрощення, перевірки коректності та експериментального модуля. Така структура дозволяє тестувати окремі етапи та не змішувати роботу production-алгоритму з обчисленням експериментальних метрик.")
table("Таблиця 5.1 – Основні компоненти програмної системи",
      ["Компонент", "Призначення"], [
          ("AdaptiveSimplifier", "Публічний WKT-in/WKT-out API, перевірка параметрів та формування діагностичного звіту."),
          ("WktIO", "Потокобезпечне читання та запис WKT засобами JTS; на кожний виклик створюється окремий reader/writer."),
          ("GeometryParts", "Розкладання LineString, MultiLineString, Polygon і MultiPolygon на лінії, оболонки й отвори та відновлення структури."),
          ("ComplexityAnalyzer", "Обчислення локальних кутових, відхилювальних, щільнісних і фрактальних ознак."),
          ("BoxCounting", "Наближене оцінювання локальної фрактальної розмірності методом підрахунку зайнятих комірок."),
          ("ToleranceModel", "Перетворення оцінки складності на згладжене поле локальних множників допуску."),
          ("VariableToleranceDP", "Варіант алгоритму Дугласа–Пекера з індивідуальним допуском для кожної вершини."),
          ("AdaptiveEngine", "Глобальне ранжування вершин, вибір порога, повторні спроби та безпечне повернення оригіналу."),
          ("GeometryValidator", "Перевірка валідності, типу, компонентів, отворів і простоти ліній."),
          ("benchmark.*", "Порівняння з JTS DouglasPeuckerSimplifier, пошук допуску, метрики, CSV та консольний звіт.")
      ])
body_paragraph("Послідовність обробки складається з таких етапів: 1) перевірка відсотка та синтаксису WKT; 2) перевірка підтримуваного типу, числового діапазону й топологічної валідності; 3) декомпозиція складеної геометрії на незалежні координатні послідовності; 4) вилучення послідовних дублікатів і канонізація початку замкнених кілець; 5) локальне оцінювання складності; 6) побудова поля допусків і дерева адаптивного спрощення; 7) вибір порога відповідно до цільового скорочення; 8) відновлення геометрії, перевірка кандидата та, за потреби, повторна спроба з менш агресивним скороченням; 9) серіалізація результату у двовимірний WKT.")
body_paragraph("Компоненти мультигеометрій, зовнішні оболонки полігонів і отвори зберігають свій порядок. Водночас поріг вилучення вершин визначається глобально для всіх частин об’єкта, що дає змогу розподіляти доступний рівень скорочення відповідно до локальної значущості вершин.")
body_paragraph("Загальну схему взаємодії компонентів доцільно подати у вигляді діаграми, на яку далі посилається опис алгоритму (рис. 5.1).")
marker("Рисунок 5.1 – Архітектура системи. Показати потік WKT → AdaptiveSimplifier → GeometryParts → ComplexityAnalyzer/BoxCounting → ToleranceModel → VariableToleranceDP/AdaptiveEngine → GeometryValidator → WKT, а benchmark-модуль винести окремою гілкою порівняння.")

heading("5.2. Реалізація оцінювання геометричної складності", 2)
body_paragraph("Локальна складність оцінюється для кожної вершини лінії або кільця. Використано чотири безрозмірні ознаки в діапазоні від 0 до 1: кут повороту, відхилення від локальної хорди, відносну щільність вершин і локальну фрактальну характеристику. Для відкритої лінії кінцеві точки отримують нульову кутову складність, оскільки в них немає двох суміжних сегментів.")
formula("aᵢ = (π − θᵢ) / π")
body_paragraph("Тут θᵢ — кут між суміжними напрямками, обчислений JTS. Для локального відхилення використовується вікно радіуса дві вершини. Визначається максимальна відстань внутрішніх точок вікна до сегмента між його крайніми точками, після чого значення нормується на довжину шляху всередині вікна:")
formula("dᵢ = clamp₀¹(2 · maxDistᵢ / pathLengthᵢ).")
body_paragraph("Щільність характеризує нерівномірність дискретизації. Нехай rᵢ — відношення середньої довжини сегмента всієї частини до середньої довжини сегмента локального вікна. Тоді qᵢ = rᵢ/(1+rᵢ). Коротші локальні сегменти дають більше значення ознаки. Усі ці величини є масштабно інваріантними, тому зміна одиниць координат не повинна змінювати сам профіль складності.")
body_paragraph("Фрактальна складова визначається методом box-counting на перекривних вікнах із 16 сегментів і кроком 8 сегментів. Для замкнених кілець вікна є циклічними. Найдовша сторона обмежувального прямокутника L ділиться на 2ʲ, де j змінюється від 1 до 6, а розмір комірки становить εⱼ = L/2ʲ. Надто дрібні масштаби, для яких εⱼ менше половини середньої довжини сегмента, не використовуються.")
code_block([
    "val cells = 1 << j",
    "val eps = side / cells",
    "val n = countBoxes(coords, from, to, minX, minY, eps, cells)",
    "xs += -math.log(eps)",
    "ys += math.log(n.toDouble)"
])
body_paragraph("Сегменти дискретизуються з кроком ε/2, після чого підраховується кількість унікальних двовимірних комірок N(ε), яких торкнулися вибірки. Фрактальна розмірність оцінюється як нахил лінійної регресії log N(ε) відносно log(1/ε). Оцінка приймається лише за наявності щонайменше трьох масштабів і коефіцієнта детермінації R² не меншого за 0,8; результат обмежується інтервалом [1; 2]. Для фрагментів коротших за вісім сегментів, нульової протяжності або нестабільної регресії фрактальна ознака вважається недоступною.")
body_paragraph("Підсумкова складність є зваженим середнім. Ваги кутової ознаки, локального відхилення, фрактальної складової та щільності становлять відповідно 0,35; 0,30; 0,25 і 0,10. Якщо box-counting не дає надійного значення, його вага вилучається, а геометричні ознаки автоматично перенормовуються. Це забезпечує визначену поведінку для коротких фрагментів без підміни нестабільної фрактальної оцінки вигаданим числом.")
table("Таблиця 5.2 – Параметри оцінювання складності за замовчуванням",
      ["Параметр", "Значення", "Зміст"], [
          ("featureHalfWindow", "2", "Радіус локального вікна геометричних ознак, у вершинах."),
          ("fractalHalfWindow", "8", "Половина 16-сегментного box-counting-вікна та крок перекриття."),
          ("fractalMinSegments", "8", "Мінімальна кількість сегментів для фрактальної оцінки."),
          ("fractalMinScales / MaxScales", "3 / 6", "Мінімальна кількість придатних масштабів і верхня межа сіток."),
          ("fractalMinR2", "0,8", "Мінімальна якість log-log регресії."),
          ("ваги", "0,35/0,30/0,25/0,10", "Кут / відхилення / фрактальна ознака / щільність.")
      ])

heading("5.3. Алгоритм адаптивного спрощення", 2)
body_paragraph("Оцінка cᵢ перетворюється на множник локального допуску за експоненційною залежністю. За відсутності згладжування вона має вигляд mᵢ = 4^(1−2cᵢ): проста ділянка з cᵢ = 0 отримує множник 4, середня складність cᵢ = 0,5 — множник 1, а максимальна складність cᵢ = 1 — множник 0,25. Отже, складніші фрагменти мають менший допуск і вищу ймовірність збереження деталей.")
formula("mᵢ = exp(meanⱼ∈Wᵢ(ln 4 · (1 − 2cⱼ))),     τᵢ = t · mᵢ.")
body_paragraph("Згладжування виконується в логарифмічному просторі у вікні радіуса дві вершини. Для кільця вікно циклічне, а для відкритої лінії — обрізається біля кінців. Це усуває різкі стрибки допуску між сусідніми вершинами та зменшує ризик появи штучних швів.")
body_paragraph("В основі спрощення лежить модифікована рекурсивна ідея Дугласа–Пекера, реалізована ітеративно. Для внутрішньої вершини i у проміжку (a, b) використовується не абсолютна відстань, а нормована величина rᵢ = dist(pᵢ, segment(pₐ,pᵦ))/mᵢ. Точка з найбільшим rᵢ стає точкою поділу. За глобального порога t проміжок ділиться, якщо max rᵢ > t. Звідси для кожної вилученої вершини випливає локальна межа distᵢ ≤ t·mᵢ.")
code_block([
    "val r = Distance.pointToSegment(coords(i), coords(a), coords(b)) / multipliers(i)",
    "if (r > bestR) { bestR = r; best = i }",
    "val significance = math.min(parentSignificance, bestR)"
])
body_paragraph("Повний прохід формує дерево поділів і значущість кожної вершини. Кінцеві точки відкритої лінії завжди є опорними. У кільці зберігаються канонічна початкова вершина, найдальша від неї вершина, вершина з максимальним відхиленням від утвореного сегмента та повторена точка замикання. Тому кільце не може скоротитися нижче трикутника.")
body_paragraph("Цільовий відсоток p переводиться у бажану кількість вилучень round(N·p/100). Послідовні дублікати, видалені на етапі підготовки, уже враховуються у цьому числі. Решта вершин усіх частин ранжуються за значущістю. Для збереження доведеної межі локальної похибки алгоритм вилучає лише повні групи однакової значущості та вибирає групу, найближчу до цілі. Через дискретність, обов’язкові опорні вершини та перевірки валідності заданий відсоток є орієнтиром, а не жорсткою гарантією.")
body_paragraph("Якщо кандидат виявляється неприйнятним, кількість вилучень зменшується приблизно за законом R·0,7ᵏ і прив’язується до попередньої повної групи значущості. Максимальна кількість кандидатів дорівнює восьми; остання спроба не вилучає ранжованих вершин. Якщо навіть очищений кандидат не може бути побудований, повертається початкова геометрія з ознакою fallback.")
body_paragraph("Профіль локальних допусків і різницю між збереженими вершинами простих та складних ділянок варто показати окремо (рис. 5.2).")
marker("Рисунок 5.2 – Приклад зміни локальної складності та множника допуску вздовж однієї лінії. Показати просту ділянку з більшим mᵢ і локально складну ділянку з меншим mᵢ; підпис: «Вплив локальної складності на адаптивний допуск».")

heading("5.4. Забезпечення коректності геометрій", 2)
body_paragraph("Коректність контролюється до та після спрощення. На вході відхиляються null, порожній текст, синтаксично неправильний WKT, непідтримуваний тип, нескінченні координати, чисельно небезпечний діапазон і топологічно невалідна геометрія. Для цих ситуацій визначено окремі винятки InvalidWktException, UnsupportedGeometryTypeException, InvalidGeometryException та InvalidReductionPercentException. Автоматичне топологічне «виправлення» не застосовується, оскільки воно могло б змінити зміст вхідного об’єкта.")
body_paragraph("Після побудови результат повинен зберігати тип геометрії, кількість компонентів і кількість полігональних отворів. JTS IsValidOp перевіряє топологічну валідність. Якщо початкова лінійна геометрія була простою, результат не повинен отримати самоперетин. Помилки конструювання кілець або інших компонентів також трактуються як відхилення кандидата й активують менш агресивну повторну спробу.")
body_paragraph("Декомпозиція та відновлення гарантують збереження зовнішніх кілець і отворів у початковому порядку. Перша й остання вершини відкритих ліній є опорними, а для кільця повторена кінцева координата не вилучається. Канонізація початку кільця потрібна лише для стабільності аналізу; напрям обходу не змінюється. Порожні підтримувані геометрії повертаються порожніми, а двоточкові лінії та трикутні кільця не спрощуються.")
body_paragraph("Експериментальний модуль додатково, не змінюючи результату алгоритму, перевіряє належність усіх вихідних координат множині вхідних, збереження кінцевих точок, замкненість кілець і структурну сумісність. Якщо відповідність вилучених вершин сегментам неможливо встановити надійно, відповідна метрика позначається як недоступна.")

heading("5.5. Технології та програмна реалізація", 2)
body_paragraph("Проєкт реалізовано мовою Scala 2.13.12 для JVM 11 і зібрано Maven. Геометричні операції, читання WKT, перевірка валідності, стандартний алгоритм Дугласа–Пекера та відстані надає JTS Topology Suite 1.19.0. Тестова частина використовує JUnit 4.13.2 та Maven Surefire 3.2.5. Основний артефакт — JAR-бібліотека, тому виклик спрощення не потребує створення JTS-об’єктів користувачем.")
code_block([
    "val simplifiedWkt = AdaptiveSimplifier.simplify(",
    "  wkt = \"LINESTRING (0 0, 1 0.2, 2 0, 3 1)\",",
    "  targetReductionPercent = 40.0",
    ")"
])
body_paragraph("Метод simplify повертає лише WKT, як передбачено публічним контрактом. Метод simplifyWithReport є необов’язковим діагностичним розширенням і містить кількість вершин, досягнуте скорочення, поріг, кількість спроб, ознаку fallback, покриття фрактальною оцінкою та причини відхилення попередніх кандидатів.")
body_paragraph("Порівняльний модуль винесено до пакета benchmark. SimplificationBenchmark запускає обидва методи на одній початковій геометрії; DouglasPeuckerMatcher підбирає глобальний допуск стандартного алгоритму; GeometryMetricsCalculator обчислює показники якості; BatchBenchmarkRunner формує CSV; ComparisonReportFormatter створює табличний консольний звіт. Таким чином, експериментальна інфраструктура не змінює евристики production-алгоритму.")

page_break()
heading("Розділ 6. Експериментальне дослідження та оцінювання результатів", 1)
body_paragraph("Метою експерименту було перевірити, чи забезпечує врахування локальної складності меншу геометричну похибку, ніж стандартний JTS DouglasPeuckerSimplifier, за зіставного фактичного скорочення кількості вершин. Порівняння виконувалося не за однаковим числовим допуском, оскільки глобальний допуск Дугласа–Пекера та нормований адаптивний поріг мають різний зміст.")

heading("6.1. Методика експерименту", 2)
body_paragraph("Вибірку сформовано з OpenStreetMap за допомогою OSMnx і Shapely. Скрипт run.py виконує обмежені запити для міських територій Львова, львівських залізничних ліній, островів Венеції та водних шляхів Амстердама. До набору включалися непорожні валідні двовимірні геометрії підтримуваних типів із кількістю координат від 4 до 2000; дублікати об’єктів вилучалися за WKB, а відбір був детермінованим. Файл wkt_examples.txt містить 61 геометрію: 30 LineString, 29 Polygon, один MultiLineString і один MultiPolygon.")
table("Таблиця 6.1 – Склад експериментальної вибірки",
      ["Група", "Типи", "Кількість"], [
          ("Лінійні геометрії", "LineString та MultiLineString", "31"),
          ("Полігональні геометрії", "Polygon та MultiPolygon", "30"),
          ("Разом", "Усі підтримувані типи", "61")
      ])
body_paragraph("Кожну геометрію оброблено для цільових рівнів 20%, 40%, 60% і 80%, тому сформовано 244 пари результатів. Спочатку запускався Adaptive із заданим відсотком. Після цього для стандартного Дугласа–Пекера виконувався обмежений пошук допуску, ціллю якого було фактичне, а не запитане скорочення Adaptive. Пошук поєднував спрямовану бісекцію, лінійні й логарифмічні проби повного діапазону та локальне уточнення; максимальний бюджет становив 30 ітерацій.")
body_paragraph("Порівняння вважалося узгодженим, якщо абсолютна різниця фактичних скорочень не перевищувала 2 відсоткові пункти, обидва алгоритми завершилися без помилки й Adaptive не повернув оригінал через fallback. Із 244 пар 213 відповідали цій умові. Решта 31 збережені для діагностики, але не включені до прямого підрахунку перемог за якістю.")
table("Таблиця 6.2 – Узгодженість рівнів скорочення",
      ["Ціль", "Усього", "Узгоджено", "Не узгоджено", "Частка узгоджених"], [
          ("20%", "61", "50", "11", "82,0%"),
          ("40%", "61", "51", "10", "83,6%"),
          ("60%", "61", "53", "8", "86,9%"),
          ("80%", "61", "59", "2", "96,7%"),
          ("Разом", "244", "213", "31", "87,3%")
      ])
body_paragraph("Координати OSM залишено в EPSG:4326. Отже, JTS виконує планарні обчислення у градусах, а площі подані у квадратних градусах. Значення придатні для порівняння двох алгоритмів на тій самій геометрії, але не повинні інтерпретуватися як метри або квадратні метри.")

heading("6.2. Метрики оцінювання", 2)
body_paragraph("Жодна окрема метрика не вважається повною оцінкою якості. Максимальне відхилення характеризує найгіршу локальну помилку, середнє відхилення — типовий рівень розбіжності, довжина та площа — інтегральні характеристики, а симетрична різниця полігонів ураховує просторовий розподіл втрачених і доданих областей.")
table("Таблиця 6.3 – Використані метрики якості",
      ["Метрика", "Визначення та застосовність"], [
          ("Кількість вершин", "JTS getNumPoints; повторена точка замикання кільця враховується."),
          ("Фактичне скорочення", "100·(N₀−N₁)/N₀; для порожньої геометрії — 0%."),
          ("Симетрична відстань Гаусдорфа", "JTS DiscreteHausdorffDistance для ліній або меж полігонів; densify fraction = 0,25."),
          ("Середнє геометричне відхилення", "Середнє найближчих відстаней у двох напрямках; перша точка частини та дві рівномірні вибірки на кожний сегмент."),
          ("Зміна довжини", "Абсолютна різниця довжин і відношення до початкової довжини; для полігона це сумарний периметр оболонки й отворів."),
          ("Зміна площі", "Абсолютна й відносна різниця площ; лише для полігональних геометрій."),
          ("Площа симетричної різниці", "Площа original △ simplified для двох валідних полігональних геометрій."),
          ("Максимальне відхилення вилучених вершин", "Максимальна перпендикулярна відстань до відповідного нового сегмента за доведеної відповідності вершин."),
          ("Структура та валідність", "Тип, компоненти, отвори, кінцеві точки, замикання кілець і належність вихідних координат вхідним."),
          ("Час", "System.nanoTime: Adaptive public call; для DP окремо фінальний запуск і пошук допуску.")
      ])
body_paragraph("Відносні зміни довжини та площі не обчислюються за нульового знаменника. Непридатні або ненадійні метрики позначаються N/A. Середнє відхилення є детермінованою дискретною апроксимацією, а не точним інтегралом уздовж кривої.")

heading("6.3. Загальний аналіз результатів", 2)
body_paragraph("Усі наведені далі підрахунки якості виконано лише для 213 узгоджених пар. Для кожної метрики кращим вважалося менше значення; рівність визначалася за точністю, надрукованою у logs.txt. Сукупний результат не підтвердив загальної переваги адаптивного методу: стандартний Дуглас–Пекер частіше мав менші відстані Гаусдорфа, середні відхилення та полігональні просторові похибки.")
table("Таблиця 6.4 – Кількість кращих результатів у 213 узгоджених порівняннях",
      ["Метрика", "Adaptive", "Douglas–Peucker", "Однаково", "Застосовних пар"], [
          ("Відстань Гаусдорфа", "18", "126", "69", "213"),
          ("Середнє геометричне відхилення", "42", "124", "47", "213"),
          ("Відносна зміна довжини", "77", "77", "59", "213"),
          ("Відносна зміна площі", "32", "68", "12", "112"),
          ("Площа симетричної різниці", "15", "88", "9", "112"),
          ("Максимальне відхилення вилучених вершин", "18", "126", "69", "213")
      ])
body_paragraph("За двома основними дистанційними метриками одночасно Adaptive був кращим у 14 випадках, Douglas–Peucker — у 110, обидві метрики збіглися у 47, а ще 42 випадки дали змішаний результат. Із 14 переваг Adaptive 13 припадали на лінії й лише одна — на полігон. Для ліній Adaptive виграв обидві метрики у 13 випадках, DP — у 33; для полігонів відповідні числа становили 1 та 77.")
body_paragraph("Зміна довжини показала іншу картину: загальна кількість перемог однакова — по 77. На рівнях 60% і 80% Adaptive мав відповідно 23 проти 20 та 25 проти 23 кращих значень. Це свідчить, що адаптивне розміщення збережених вершин інколи краще підтримує сумарну довжину навіть тоді, коли максимальна відстань є більшою.")
body_paragraph("Для полігонів відносна зміна площі не завжди узгоджувалася з площею симетричної різниці. Похибки додавання та втрати площі можуть взаємно компенсуватися, тому мала зміна загальної площі ще не означає близькість контурів. Саме тому 32 перемоги Adaptive за відносною площею супроводжуються лише 15 перемогами за симетричною різницею, тоді як DP має відповідно 68 і 88.")
table("Таблиця 6.5 – Переваги за двома дистанційними метриками залежно від цілі",
      ["Ціль", "Узгоджено", "Adaptive кращий за обома", "DP кращий за обома", "Обидві однакові", "Змішані"], [
          ("20%", "50", "1", "21", "17", "11"),
          ("40%", "51", "5", "27", "9", "10"),
          ("60%", "53", "4", "30", "10", "9"),
          ("80%", "59", "4", "32", "11", "12")
      ])
body_paragraph("Важливим позитивним результатом є структурна надійність. У всіх 244 запусках обидва методи сформували валідні геометрії, зберегли тип, кількість компонентів і належність вихідних координат вхідним. Для 120 полігональних запусків збережено отвори й замикання кілець, а для 124 лінійних — кінцеві точки. Adaptive жодного разу не активував fallback у цьому наборі.")
table("Таблиця 6.6 – Структурні результати для всіх 244 запусків",
      ["Перевірка", "Adaptive", "Douglas–Peucker"], [
          ("Валідний результат", "244/244", "244/244"),
          ("Тип і кількість компонентів збережено", "244/244", "244/244"),
          ("Координати результату належать вхідним", "244/244", "244/244"),
          ("Кінцеві точки ліній збережено", "124/124", "124/124"),
          ("Отвори та замикання полігонів збережено", "120/120", "120/120"),
          ("Fallback", "0", "N/A")
      ])
body_paragraph("Для наочного подання загальної картини доцільно використати груповану діаграму кількості перемог за метриками (рис. 6.1).")
marker("Рисунок 6.1 – Кількість перемог Adaptive, Douglas–Peucker і рівних результатів у 213 узгоджених парах. Окремо показати Hausdorff, mean deviation, length distortion, а для 112 полігонів — area distortion і symmetric difference area.")

heading("6.4. Аналіз показових прикладів", 2)
body_paragraph("Попри перевагу DP в агрегованих дистанційних показниках, виявлено конкретні геометрії, де локально адаптивний підхід істотно зменшив похибку. Ідентифікатори відновлено за порядком рядків wkt_examples.txt та стабільним SHA-256-ідентифікатором batch-модуля. Далі наведено чотири попередньо визначені приклади, усі з узгодженими скороченнями й валідною структурою.")
table("Таблиця 6.7 – Показові випадки переваги Adaptive",
      ["ID, ціль", "Фактичне скорочення A / DP", "Hausdorff A / DP", "Mean deviation A / DP"], [
          ("record-00016-aae85b5057cf, 40%", "40,2299% / 40,2299%", "9,290960·10⁻⁸ / 7,583132·10⁻⁷", "9,668835·10⁻⁹ / 1,743739·10⁻⁸"),
          ("record-00027-77f43f50ff9f, 80%", "79,4118% / 79,4118%", "2,018972·10⁻⁵ / 5,600816·10⁻⁵", "5,823366·10⁻⁶ / 1,045134·10⁻⁵"),
          ("record-00051-57bddba92499, 40%", "38,4615% / 38,4615%", "3,676925·10⁻⁵ / 6,610464·10⁻⁵", "9,316380·10⁻⁶ / 1,291027·10⁻⁵"),
          ("record-00005-7950f78f4ff0, 40%", "38,5965% / 38,5965%", "2,666617·10⁻⁵ / 3,666320·10⁻⁵", "3,499824·10⁻⁶ / 3,740068·10⁻⁶")
      ])
body_paragraph("Найсильніший випадок — record-00016-aae85b5057cf, залізнична лінія Львова з 87 вершинами. За однакового скорочення до 52 вершин Adaptive мав на 87,75% меншу відстань Гаусдорфа та на 44,55% менше середнє відхилення. Максимальне відхилення вилучених вершин також зменшилося з 7,583132·10⁻⁷ до 9,290960·10⁻⁸, а похибка довжини — приблизно з 1,7004·10⁻⁷ до 1,1817·10⁻⁸ у відносних одиницях. Відмінності наборів збережених точок варто показати на рис. 6.2.")
marker("Рисунок 6.2 – Порівняння оригіналу, Adaptive та Douglas–Peucker для record-00016-aae85b5057cf за цілі 40%. Показати всі три лінії, збережені та вилучені вершини; підпис: «Спрощення нерівномірно дискретизованої залізничної лінії».")
body_paragraph("Для record-00027-77f43f50ff9f за цілі 80% обидва алгоритми скоротили 34 вершини до 7. Adaptive зменшив Hausdorff на 63,95%, а mean deviation — на 44,28% відносно DP; похибка довжини становила 0,0425% проти 0,0621%. Цей результат важливий як приклад агресивного скорочення, за якого вибір кількох опорних вершин визначає загальну форму (рис. 6.3).")
marker("Рисунок 6.3 – Порівняння record-00027-77f43f50ff9f за цілі 80% (34 → 7 вершин). Виділити ділянки, де різне розташування опорних вершин змінює максимальне та середнє відхилення; запропонований підпис: «Агресивне спрощення короткої залізничної лінії».")
body_paragraph("Record-00051-57bddba92499 — водний шлях Амстердама з 13 вершинами. За скорочення 38,4615% Adaptive зменшив Hausdorff на 44,38%, mean deviation на 27,84% і відносну похибку довжини з 0,2421% до 0,1330%. Для короткої лінії кожна з п’яти вилучених вершин суттєво впливає на нові сегменти, що робить приклад зручним для візуального пояснення (рис. 6.4).")
marker("Рисунок 6.4 – Порівняння record-00051-57bddba92499 за цілі 40% (13 → 8 вершин). Показати локальний вигин водного шляху й точки, залишені кожним методом; підпис: «Збереження локальної форми короткого водного шляху».")
body_paragraph("Єдиним полігоном, де Adaptive одночасно мав менші Hausdorff і mean deviation, став record-00005-7950f78f4ff0 за цілі 40%. Обидва методи скоротили 57 координат до 35. Adaptive був кращим за Hausdorff на 27,27% і за mean deviation на 6,42%, а також незначно меншим був symmetric difference area: 7,381321·10⁻⁸ проти 7,448745·10⁻⁸. Водночас DP трохи краще зберіг довжину й загальну площу. Це змішаний результат, а не безумовна перемога Adaptive (рис. 6.5).")
marker("Рисунок 6.5 – Порівняння полігона record-00005-7950f78f4ff0 за цілі 40%. Показати нерегулярний контур, ділянки значних кутових змін і області symmetric difference; підпис: «Змішаний результат адаптивного спрощення полігональної межі».")
body_paragraph("Аналіз вихідних WKT показав, що 13 із 14 випадків одночасної переваги за двома дистанційними метриками є лініями. Для цих спостережень середній коефіцієнт варіації довжин сегментів дорівнював приблизно 1,30, середнє відношення найдовшого сегмента до найкоротшого — близько 101, а 90-й процентиль кута повороту — близько 16°. Отже, це переважно плавні лінії з нерівномірною дискретизацією та локальними змінами напрямку, а не контури, що складаються лише з гострих кутів.")
body_paragraph("Можливе пояснення полягає у взаємодії ознаки локальної щільності, відхилення від хорди та змінного допуску: густо оцифрована важлива ділянка може отримати менший множник допуску, тоді як простіша частина — більший. Це лише інтерпретація механізму. Глобальні характеристики не доводять причинність: середній коефіцієнт варіації сегментів у лінійних випадках, де DP виграв обидві метрики, був дуже близьким — приблизно 1,32.")
body_paragraph("Для об’єктивності необхідно розглянути й протилежні приклади. На record-00052-9c3c443c3a59 за цілі 60% DP мав Hausdorff приблизно 1,32·10⁻⁴ проти 4,08·10⁻⁴ Adaptive та mean deviation 1,384676·10⁻⁵ проти 8,186813·10⁻⁵. На великому венеційському полігоні record-00032-af4bf89dd793 за цілі 60% DP також був кращим: 1,417091·10⁻⁵ проти 2,529430·10⁻⁵ за Hausdorff і 1,751212·10⁻⁶ проти 2,727513·10⁻⁶ за середнім відхиленням. Це показує, що сама нерівномірність або велика кількість вершин не гарантує переваги локальної адаптації (рис. 6.6).")
marker("Рисунок 6.6 – Репрезентативний випадок переваги Douglas–Peucker: record-00052-9c3c443c3a59 за цілі 60%. Показати оригінал і обидва результати, виділити сегмент із найбільшим відхиленням Adaptive; підпис: «Приклад, у якому глобальний допуск DP краще зберігає форму».")

heading("6.5. Продуктивність і обмеження", 2)
body_paragraph("За журналом 244 запусків середній час Adaptive становив приблизно 1,84 мс, медіана — 1,027 мс. Для одного фінального запуску DP після вже виконаного підбору допуску середнє дорівнювало 0,034 мс, медіана — 0,009 мс. Таке пряме зіставлення не є повністю симетричним: таймер Adaptive охоплює публічний виклик із parsing, перевірками, ознаками, ранжуванням, побудовою й WKT-серіалізацією, тоді як runtime DP вимірює лише один запуск на вже розібраній геометрії.")
body_paragraph("Час пошуку допуску DP записувався окремо. Якщо додати його до фінального запуску, DP був швидшим у 138 із 213 узгоджених випадків, Adaptive — у 75. Для ліній DP був швидшим у 93 зі 101 випадку, тоді як для полігонів Adaptive був швидшим у 67 зі 112. Ці значення є діагностичними одиничними вимірюваннями: не виконувалися JVM warm-up, окремі fork, контроль GC, повторні серії та статистичне оцінювання. Тому вони не є доказом стабільної продуктивності.")
body_paragraph("Основними обмеженнями дослідження є: евристичні, не відкалібровані ваги й розміри вікон; наближений підрахунок комірок; планарні обчислення для географічних координат; дискретна Hausdorff-метрика та лише дві вибірки на сегмент для середнього відхилення; повторні вимірювання тих самих 61 об’єкта на чотирьох рівнях; відсутність довірчих інтервалів; незалежне спрощення сусідніх об’єктів без узгодження спільних меж; квадратична найгірша складність variable DP.")
body_paragraph("Окремою методологічною проблемою є 31 неузгоджена пара. Вона не свідчить про помилку алгоритму: через дискретну кількість вершин DP не завжди може досягти близького скорочення. Вилучення цих пар потрібне для справедливого зіставлення якості, але може створювати зміщення, якщо складні для узгодження геометрії систематично відрізняються від інших.")

heading("6.6. Висновки за результатами дослідження", 2)
body_paragraph("Реалізована система підтвердила працездатність підходу до локально адаптивного спрощення: усі дослідні геометрії оброблено без втрати валідності, типу, компонентів, отворів, кінцевих точок і замикання кілець. У 213 випадках вдалося забезпечити зіставний із DP фактичний рівень скорочення.")
body_paragraph("Агрегований результат не підтверджує універсальної переваги Adaptive. Стандартний Дуглас–Пекер частіше давав меншу максимальну та середню геометричну похибку, особливо для полігонів. Водночас однакова кількість перемог за відносною зміною довжини та 14 конкретних випадків переваги Adaptive за обома дистанційними метриками підтверджують, що локальний підхід може бути корисним для окремого класу об’єктів.")
body_paragraph("Найвиразніші позитивні приклади — нерівномірно дискретизовані залізничні та водні лінії, у яких різні ділянки мають різну локальну значущість. Виміряні покращення на record-00016, record-00027 і record-00051 показують потенціал адаптивного розподілу допуску. Однак припущення про причину цих переваг потребує окремої перевірки на ширшій вибірці та шляхом аналізу чутливості параметрів.")
body_paragraph("Отже, практичний результат роботи полягає не в доведенні безумовної переваги нового методу, а у створенні відтворюваної реалізації й експериментальної інфраструктури, яка дозволяє визначати умови, за яких адаптивне спрощення є доцільним, та об’єктивно фіксувати випадки, де стандартний підхід залишається кращим.")

# Start the existing conclusion on a new page and restore it without changing its XML.
page_break()
for element in tail:
    body.insert(body.index(sect_pr), element)

# Supplement, but do not rewrite, the existing theoretical conclusion.
body_paragraph("У практичній частині сформовану концепцію реалізовано як окрему Scala/JTS-бібліотеку з публічним WKT-інтерфейсом. Розроблено локальне оцінювання складності на основі box-counting, кута повороту, відхилення від хорди та щільності вершин, а також алгоритм змінного допуску, у якому складні ділянки обробляються обережніше. Передбачено збереження структури геометрій, обмежені повторні спроби та безпечне повернення оригіналу.")
body_paragraph("Експериментальна перевірка охопила 61 OSM-геометрію та 244 порівняння на рівнях 20%, 40%, 60% і 80%. Із них 213 пар мали зіставне фактичне скорочення. В усіх запусках обидва методи сформували валідні результати зі збереженням контрольованих структурних властивостей.")
body_paragraph("Отримані дані не підтвердили загальної переваги Adaptive: Douglas–Peucker частіше мав менші дистанційні та полігональні просторові похибки. Водночас Adaptive був рівноцінним за загальною кількістю перемог у збереженні довжини та продемонстрував менші Hausdorff і mean deviation у 14 узгоджених випадках, переважно для нерівномірно дискретизованих ліній. На окремих прикладах зменшення обох похибок було суттєвим.")
body_paragraph("Таким чином, гіпотезу доцільно уточнити: врахування локальної складності не гарантує кращого результату для довільної геометрії, але може забезпечити перевагу для об’єктів із неоднорідною локальною структурою. Подальша робота має включати калібрування ваг, дослідження чутливості, використання проєктованих систем координат, ширшу незалежну вибірку та контрольоване вимірювання продуктивності.")

# Ask Word to refresh TOC/PAGE fields when the document is opened.
settings = doc.settings.element
update = settings.find(qn('w:updateFields'))
if update is None:
    update = OxmlElement('w:updateFields')
    settings.append(update)
update.set(qn('w:val'), 'true')

doc.save(OUTPUT)

# Reopen and perform structural checks.
check = Document(OUTPUT)
assert len(check.sections) == len(Document(SOURCE).sections)
assert any(p.text.startswith('Розділ 5.') for p in check.paragraphs)
assert any(p.text.startswith('Розділ 6.') for p in check.paragraphs)
assert any('record-00016-aae85b5057cf' in p.text for p in check.paragraphs)
assert len(check.tables) == 9
assert len(check.inline_shapes) == len(Document(SOURCE).inline_shapes)
# The first 137 paragraph texts/styles (the theoretical body before conclusion) remain unchanged.
orig = Document(SOURCE)
for old, new in zip(orig.paragraphs[:137], check.paragraphs[:137]):
    assert old.text == new.text and old.style.name == new.style.name
# Existing media stay byte-identical; header/footer text and fields remain semantically present.
with ZipFile(SOURCE) as a, ZipFile(OUTPUT) as b:
    media = [n for n in a.namelist() if n.startswith('word/media/')]
    for name in media:
        assert name in b.namelist() and a.read(name) == b.read(name)
    header_footer = [n for n in a.namelist() if n.startswith('word/header') or n.startswith('word/footer')]
    for name in header_footer:
        assert name in b.namelist()
        old_xml = etree.fromstring(a.read(name))
        new_xml = etree.fromstring(b.read(name))
        old_text = ''.join(old_xml.xpath('.//w:t/text()', namespaces={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}))
        new_text = ''.join(new_xml.xpath('.//w:t/text()', namespaces={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}))
        old_fields = old_xml.xpath('.//w:instrText/text()', namespaces={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'})
        new_fields = new_xml.xpath('.//w:instrText/text()', namespaces={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'})
        assert old_text == new_text and old_fields == new_fields
print(f'WROTE {OUTPUT} paragraphs={len(check.paragraphs)} tables={len(check.tables)} placeholders={sum("ПОТРІБНО ДОДАТИ РИСУНОК" in p.text for p in check.paragraphs)}')
